<template><aside class="parts-tray" :class="`parts-${store.activeStep}`" aria-label="Parts selection"><button v-for="part in parts" :key="part.id" class="dial-part" :class="{selected:selectedId===part.id,disabled:!compatible(part)}" @click="select(part)"><span class="dial-disc" :class="part.type" :style="part.type==='dial'?{'--dial':part.color,'--glow':part.glow}:{}"><i v-for="n in part.type==='dial'?12:3" :key="n" :style="part.type==='dial'?{transform:`rotate(${n*30}deg)`}:{}" /></span><span class="part-meta"><b>{{ part.name }}</b><small>{{ part.sku || part.frequency || part.model }} · {{ part.price ? `+ ¥${part.price}` : 'STANDARD' }}</small><em v-if="!compatible(part)">NOT COMPATIBLE</em></span></button></aside></template>
<script setup>
import { computed } from 'vue'; import { useWatchBuilderStore } from '../stores/watchBuilder'; import { partCatalog } from '../data/watchParts'; import { isCompatible } from '../utils/compatibility'
const store=useWatchBuilderStore(); const parts=computed(()=>partCatalog[store.activeStep]||[]); const selectedId=computed(()=>store.build[store.activeStep]); const compatible=(part)=>isCompatible(part,store.build)
function select(part){ if(!compatible(part)) return; const action={case:'selectCase',dial:'selectDial',hands:'selectHands',strap:'selectStrap',caseback:'selectCaseback'}[store.activeStep]; store[action]?.(part.id) }
</script>
